with flattened as (select id, service, host, log_ts, level, latency_ms, k, attr_value from app_logs lateral view outer explode(context) t as k, attr_value) select id, service, log_ts, latency_ms, k, case when service rlike '^(billing|auth)$' then 'PRIORITY' when service rlike '^(search|checkout)$' then 'OTHER_ZONE' else 'EXTENDED' end as service_zone from flattened order by id asc nulls last;
